// ─────────────────────────────────────────────
// NODE 2: Validate & normalise incoming payload
// ─────────────────────────────────────────────
const body = $input.first().json.body || $input.first().json;

function makeUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const required = ['tenant_id', 'customer_phone', 'platform', 'message_type'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}

if (body.message_type === 'text' && !body.message) {
  throw new Error('Message content is empty');
}

return [{
  json: {
    tenant_id:           body.tenant_id,
    customer_phone:      String(body.customer_phone),
    customer_name:       body.customer_name || 'Customer',
    platform:            body.platform || 'whatsapp',
    message_type:        body.message_type || 'text',
    message:             body.message || '',
    external_message_id: body.external_message_id || makeUUID(),
    phone_number_id:     body.phone_number_id || '',
    timestamp:           body.timestamp || new Date().toISOString(),
    processed_at:        new Date().toISOString()
  }
}];

// ─────────────────────────────────────────────
// NODE 3: Detect language from message content
// ─────────────────────────────────────────────
const body = $input.first().json;
const message = body.message || '';

let detected_language = 'en';
const arabicChars = (message.match(/[\u0600-\u06FF]/g) || []).length;
const urduChars   = (message.match(/[\u067E\u0686\u0698\u06AF\u06BA\u06C1\u06BE\u06CC]/g) || []).length;

if (arabicChars > 0) {
  detected_language = (urduChars / arabicChars > 0.15) ? 'ur' : 'ar';
}

return [{ json: { ...body, detected_language, normalized_message: message.trim() } }];

// ─────────────────────────────────────────────
// NODE 5: Merge tenant with request + status check
// ─────────────────────────────────────────────
const requestData  = $('Detect Language').first().json;
const tenantItems  = $input.all();

if (!tenantItems || tenantItems.length === 0 || !tenantItems[0].json.id) {
  throw new Error('Tenant not found for id: ' + requestData.tenant_id);
}

const tenant = tenantItems[0].json;

if (tenant.status && tenant.status !== 'active') {
  throw new Error('TENANT_SUSPENDED');
}

return [{
  json: {
    // Request fields
    tenant_id:           requestData.tenant_id,
    customer_phone:      requestData.customer_phone,
    customer_name:       requestData.customer_name,
    platform:            requestData.platform,
    message_type:        requestData.message_type,
    message:             requestData.message,
    external_message_id: requestData.external_message_id,
    phone_number_id:     requestData.phone_number_id,
    processed_at:        requestData.processed_at,
    detected_language:   requestData.detected_language,
    normalized_message:  requestData.normalized_message,

    // Tenant fields
    tenant:              tenant,
    business_name:       tenant.business_name || tenant.name,
    niche:               tenant.niche || 'general',
    wa_phone_number_id:  tenant.wa_phone_number_id,
    wa_access_token:     tenant.wa_access_token,

    // AI config — from migrated columns (fallback to safe defaults)
    ai_model:            tenant.ai_model       || 'gpt-4o-mini',
    ai_temperature:      parseFloat(tenant.ai_temperature) || 0.7,
    ai_max_tokens:       parseInt(tenant.ai_max_tokens)    || 500,
    ai_language:         tenant.ai_language    || requestData.detected_language || 'ar'
  }
}];

// ─────────────────────────────────────────────
// NODE 8: Prepare OpenAI embedding request body
// ─────────────────────────────────────────────
const ctx = $('Merge Tenant').first().json;

const embedBody = JSON.stringify({
  model: 'text-embedding-3-small',
  input: ctx.normalized_message
});

return [{ json: { ...ctx, embed_request_body: embedBody } }];

// ─────────────────────────────────────────────
// NODE 10: Prepare vector search request body
// ─────────────────────────────────────────────
const ctx       = $('Merge Tenant').first().json;
const embedResp = $input.first().json;

// Extract embedding vector — gracefully handle embedding failure
const embedding = embedResp?.data?.[0]?.embedding || [];

const searchBody = JSON.stringify({
  query_embedding: embedding,
  p_tenant_id:     ctx.tenant_id,
  match_threshold: 0.70,
  match_count:     5
});

return [{ json: { ...ctx, embedding, search_request_body: searchBody } }];

// ─────────────────────────────────────────────
// NODE 12: Assemble full context for AI
// ─────────────────────────────────────────────
const ctx       = $('Merge Tenant').first().json;
const agentItem = $('Load Agent').first().json;
const convItem  = $('Find Conversation').first().json;
const kbResult  = $input.first().json;

// Agent prompt — from agents table
const agent      = agentItem?.id ? agentItem : null;
const agentPrompt = agent?.prompt ||
  `You are a helpful AI assistant for ${ctx.business_name}. Answer customer questions professionally.`;

// Knowledge base — from vector search results
const kbDocs = Array.isArray(kbResult) ? kbResult : [];
const kbEntries = kbDocs.length > 0
  ? kbDocs.map((kb, i) => `[${i + 1}] ${kb.title}:\n${kb.content}`).join('\n\n')
  : '';

// Existing conversation
const existingConv      = convItem?.id ? convItem : null;
const conversation_id   = existingConv?.id || null;
const is_new_conversation = !existingConv;

return [{
  json: {
    ...ctx,
    agent_prompt:       agentPrompt,
    kb_entries:         kbEntries,
    kb_count:           kbDocs.length,
    conversation_id:    conversation_id,
    is_new_conversation: is_new_conversation
  }
}];

// ─────────────────────────────────────────────
// NODE 14: Build complete AI prompt
// ─────────────────────────────────────────────
const ctx          = $('Assemble Context').first().json;
const historyItems = $input.all();

// Parse conversation history from messages table
const history = historyItems
  .map(item => item.json)
  .filter(m => m.id && m.content)
  .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

const language = ctx.detected_language || 'ar';

const nicheInstructions = {
  restaurant:    'You help customers with menu items, prices, opening hours, delivery, and reservations.',
  dental:        'You help patients with appointments, treatments, pricing, and clinic hours. Always recommend professional consultation.',
  real_estate:   'You help clients find properties, understand pricing, and arrange viewings.',
  salon:         'You help with bookings, services, available slots, and pricing.',
  ecommerce:     'You help with products, availability, orders, delivery, and returns.',
  food_delivery: 'You help with order tracking, menu items, delivery times, and issues.',
  medical:       'You help with appointments and general clinic information. Always recommend professional medical consultation.',
  general:       'You help customers with their inquiries professionally and helpfully.'
};

const languageInstructions = {
  ar: 'يجب أن تجيب باللغة العربية الفصحى أو بنفس لهجة العميل. اجعل ردودك طبيعية ودافئة.',
  ur: 'آپ کو اردو میں جواب دینا ہے۔ قدرتی اور دوستانہ زبان استعمال کریں۔',
  en: 'Reply in clear, warm, conversational English.'
};

// Build knowledge base section
const kbSection = ctx.kb_entries
  ? `KNOWLEDGE BASE (${ctx.kb_count} relevant results):\n${ctx.kb_entries}`
  : 'KNOWLEDGE BASE: No specific content found. Answer only from what you know about this business from the system prompt above.';

const systemPrompt = [
  `You are the AI assistant for ${ctx.business_name}.`,
  `Business type: ${ctx.niche || 'general'}`,
  '',
  ctx.agent_prompt,
  '',
  nicheInstructions[ctx.niche] || nicheInstructions.general,
  languageInstructions[language] || languageInstructions.en,
  '',
  '--- RULES ---',
  '1. Answer ONLY using the knowledge base content provided below.',
  '2. If the answer is not in the knowledge base, say you will connect the customer with a team member.',
  '3. NEVER invent prices, hours, availability, or contact details.',
  '4. Keep responses under 3 short paragraphs — be concise.',
  '5. Be warm, human, and conversational. Never sound robotic.',
  `6. Channel: ${ctx.platform}`,
  '',
  kbSection
].join('\n');

// Build messages array for OpenAI
const messages = [{ role: 'system', content: systemPrompt }];

// Add previous turns from messages table
for (const msg of history) {
  if (msg.sender_type === 'customer') {
    messages.push({ role: 'user', content: msg.content });
  } else if (msg.sender_type === 'bot') {
    messages.push({ role: 'assistant', content: msg.content });
  }
}

// Add current customer message
messages.push({ role: 'user', content: ctx.normalized_message });

return [{
  json: {
    ...ctx,
    prompt_messages: messages,
    system_prompt:   systemPrompt
  }
}];

// ─────────────────────────────────────────────
// NODE 15: Prepare GPT request body
// Uses ai_model, ai_temperature, ai_max_tokens from migrated tenant columns
// ─────────────────────────────────────────────
const ctx = $input.first().json;

// These values come from tenants.ai_model / ai_temperature / ai_max_tokens
// set in Merge Tenant node — falls back to safe defaults
const model       = ctx.ai_model       || 'gpt-4o-mini';
const temperature = parseFloat(ctx.ai_temperature) || 0.7;
const max_tokens  = parseInt(ctx.ai_max_tokens)    || 500;

const gptBody = JSON.stringify({
  model:       model,
  messages:    ctx.prompt_messages,
  temperature: temperature,
  max_tokens:  max_tokens
});

return [{
  json: {
    ...ctx,
    gpt_request_body: gptBody,
    model_used:       model
  }
}];

// ─────────────────────────────────────────────
// NODE 17: Extract AI reply from OpenAI response
// ─────────────────────────────────────────────
const response = $input.first().json;
const ctx      = $('Build AI Prompt').first().json;

if (!response.choices || !response.choices[0]) {
  throw new Error('GPT returned no response: ' + JSON.stringify(response).slice(0, 300));
}

const ai_reply         = response.choices[0].message.content;
const prompt_tokens    = response.usage?.prompt_tokens    || 0;
const completion_tokens = response.usage?.completion_tokens || 0;
const latency_ms       = Date.now() - new Date(ctx.processed_at).getTime();

return [{
  json: {
    ...ctx,
    ai_reply,
    prompt_tokens,
    completion_tokens,
    latency_ms
  }
}];

// ─────────────────────────────────────────────
// NODE 18: Prepare conversation upsert body
// Uses migrated columns: customer_phone, detected_language, last_message_at
// ─────────────────────────────────────────────
const ctx = $input.first().json;

const convBody = JSON.stringify({
  tenant_id:                ctx.tenant_id,
  platform:                 ctx.platform,
  external_conversation_id: ctx.customer_phone,
  customer_name:            ctx.customer_name,
  customer_phone:           ctx.customer_phone,
  detected_language:        ctx.detected_language,
  status:                   'open',
  bot_enabled:              true,
  last_message_at:          new Date().toISOString(),
  last_message_preview:     ctx.normalized_message.slice(0, 100),
  updated_at:               new Date().toISOString()
});

return [{ json: { ...ctx, conv_request_body: convBody } }];

// ─────────────────────────────────────────────
// NODE 20: Resolve conversation ID from upsert result
// ─────────────────────────────────────────────
const ctx          = $('Extract AI Reply').first().json;
const upsertResult = $input.first().json;

// Supabase returns array when Prefer: return=representation
const conv_id =
  (Array.isArray(upsertResult) && upsertResult[0]?.id)
    ? upsertResult[0].id
    : (upsertResult?.id || ctx.conversation_id || null);

return [{ json: { ...ctx, resolved_conversation_id: conv_id } }];

// ─────────────────────────────────────────────
// NODE 21: Prepare messages insert body
// Saves BOTH customer message AND bot reply in one request
// Uses migrated columns: model_used, prompt_tokens, completion_tokens,
//   latency_ms, kb_chunks_used, detected_language
// ─────────────────────────────────────────────
const ctx   = $input.first().json;
const conv_id = ctx.resolved_conversation_id;

const messagesBody = JSON.stringify([
  {
    conversation_id:    conv_id,
    sender_type:        'customer',
    content:            ctx.normalized_message,
    external_message_id: ctx.external_message_id,
    detected_language:  ctx.detected_language,
    is_read:            false
  },
  {
    conversation_id:   conv_id,
    sender_type:       'bot',
    content:           ctx.ai_reply,
    model_used:        ctx.model_used,
    prompt_tokens:     ctx.prompt_tokens,
    completion_tokens: ctx.completion_tokens,
    latency_ms:        ctx.latency_ms,
    kb_chunks_used:    ctx.kb_count || 0,
    detected_language: ctx.detected_language,
    is_read:           true
  }
]);

return [{ json: { ...ctx, messages_request_body: messagesBody } }];

// ─────────────────────────────────────────────
// NODE 23: Build final response JSON
// ─────────────────────────────────────────────
const ctx = $('Get Conversation ID').first().json;

return [{
  json: {
    success:         true,
    reply:           ctx.ai_reply,
    language:        ctx.detected_language,
    conversation_id: ctx.resolved_conversation_id,
    tenant_id:       ctx.tenant_id,
    model_used:      ctx.model_used,
    kb_chunks_used:  ctx.kb_count || 0,
    latency_ms:      ctx.latency_ms
  }
}];

// ─────────────────────────────────────────────
// NODE: Detect Intent & Create Record
// ─────────────────────────────────────────────
const ctx = $('Extract AI Reply').first().json;
const msg = ctx.message || ctx.normalized_message || '';
const msgLower = msg.toLowerCase();
const aiReply = ctx.ai_reply || '';

function detectIntent(text) {
  const m = text.toLowerCase();
  if (/order confirm|confirm kar|haan confirm|yes confirm|ok confirm/.test(m)) return 'order_confirmed';
  if (/deliver|address|location|ghar|makan|city|phase|block|dha|clifton/.test(m)) return 'address_provided';
  if (/\bcod\b|cash on delivery|easypaisa|jazzcash|bank transfer|payment/.test(m)) return 'cod_request';
  if (/want|need|order|chahiye|chaie|buy|purchase|kitna|price|rate/.test(m)) return 'order_placement';
  if (/appointment|book|slot|visit|checkup|schedule/.test(m)) return 'booking_intent';
  if (/property|flat|house|apartment|plot|rent|buy|bedroom/.test(m)) return 'property_inquiry';
  if (/price|cost|rate|how much|kitna|menu|list|products|services/.test(m)) return 'product_inquiry';
  return 'general_inquiry';
}

const intent = detectIntent(msg);

// ── Restore previous extracted info (Assuming we add a Find Context node later, or we can just leave it empty for now. But wait, in v3, we don't fetch conversation_context yet. We should ideally fetch it or initialize it.)
// For now, initialize empty.
const previousInfo = {}; 

let createRecord = false;
let recordType = null;
let recordData = { ...previousInfo };

const niche = ctx.niche || 'general';

// ═══════════════════════════════════════════════════════════════
// ECOMMERCE / RESTAURANT
// ═══════════════════════════════════════════════════════════════
if (['ecommerce', 'restaurant'].includes(niche)) {
  const orderTriggerIntents = ['product_inquiry', 'order_placement', 'address_provided', 'order_confirmed', 'cod_request'];
  const shouldCreateOrder = orderTriggerIntents.includes(intent);

  if (shouldCreateOrder) {
    createRecord = true;
    recordType = 'order';

    let extractedItems = [];
    const cleanName = s => s.trim().replace(/\s+/g, ' ').replace(/^(i want|mujhe|muje|mjhe|chahiye|chahie|chaie|order|please|kindly)\s+/gi, '').trim();

    const patA = /(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items|x)\s+(?:of\s+)?([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{2,50}?)(?=\s*(?:chaie|chahiye|chahie|order|deliver|pkr|rs|\.|,|$|\n))/gi;
    const patB = /([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{2,50}?)\s+(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items|x)(?:\s|$|,)/gi;
    const patC = /(?:i\s+want|i\s+need|i\s+would\s+like|send\s+me|give\s+me)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{1,50}?)\s+(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items)/gi;
    const patD = /(?:mujhe|muje|mjhe|mjhay)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{2,50}?)(?:\s+chaie|\s+chahiye|\s+chahie|\s+chahiyen|\s+lena|\s+order)/gi;
    const patE = /(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{2,50})(?=\s|$|,)/gi;

    patC.lastIndex = 0;
    const matchesC = [...msg.matchAll(patC)];
    if (matchesC.length > 0) {
      extractedItems = matchesC.map(m => ({ name: cleanName(m[1] || ''), qty: parseInt(m[2]) || 1, price: 0 })).filter(i => i.name.length > 1);
    }
    if (extractedItems.length === 0) {
      patA.lastIndex = 0;
      const matchesA = [...msg.matchAll(patA)];
      if (matchesA.length > 0) {
        extractedItems = matchesA.map(m => ({ name: cleanName(m[2] || ''), qty: parseInt(m[1]) || 1, price: 0 })).filter(i => i.name.length > 1);
      }
    }
    if (extractedItems.length === 0) {
      patE.lastIndex = 0;
      const matchesE = [...msg.matchAll(patE)];
      if (matchesE.length > 0) {
        extractedItems = matchesE.map(m => ({ name: cleanName(m[2] || ''), qty: parseInt(m[1]) || 1, price: 0 })).filter(i => i.name.length > 1);
      }
    }
    if (extractedItems.length === 0) {
      patB.lastIndex = 0;
      const matchesB = [...msg.matchAll(patB)];
      if (matchesB.length > 0) {
        extractedItems = matchesB.map(m => ({ name: cleanName(m[1] || ''), qty: parseInt(m[2]) || 1, price: 0 })).filter(i => i.name.length > 1);
      }
    }
    if (extractedItems.length === 0) {
      patD.lastIndex = 0;
      const matchesD = [...msg.matchAll(patD)];
      if (matchesD.length > 0) {
        extractedItems = matchesD.map(m => ({ name: cleanName(m[1] || ''), qty: 1, price: 0 })).filter(i => i.name.length > 1);
      }
    }

    const unitPriceMatch = aiReply.match(/(?:PKR|Rs\.?|pkr)\s*([\d,]+)\s*(?:\/pack|\/piece|\/pcs|each)/i);
    const totalMatch = aiReply.match(/\*{0,2}[Tt]otal\*{0,2}\s*[:\-]\s*(?:PKR|Rs\.?|pkr)\s*([\d,]+)/i);

    let unitPrice = unitPriceMatch ? parseInt(unitPriceMatch[1].replace(/,/g, '')) : 0;
    let orderTotal = totalMatch ? parseInt(totalMatch[1].replace(/,/g, '')) : 0;

    if (extractedItems.length > 0) {
      if (unitPrice > 0) extractedItems[0].price = unitPrice;
      else if (orderTotal > 0 && extractedItems[0].qty > 0) {
        extractedItems[0].price = Math.round(orderTotal / extractedItems[0].qty);
      }
    }

    if (extractedItems.length > 0 && extractedItems[0].qty === 1) {
      const aiQtyMatch = aiReply.match(/[Qq]uantity\*{0,2}\s*[:\-]\s*(\d+)/);
      if (aiQtyMatch) extractedItems[0].qty = parseInt(aiQtyMatch[1]);
    }

    let currentItems = recordData.items || [];
    if (extractedItems.length > 0) {
      currentItems = extractedItems;
    }

    let deliveryAddress = recordData.delivery_address || null;
    const combinedForAddr = msg + ' ' + aiReply;
    const addrLabelMatch = combinedForAddr.match(/(?:[Dd]elivery\s+[Aa]ddress|[Dd]eliver\s+to)\s*[:\-]?\s*([^\n,\.]{8,100})/i);
    if (addrLabelMatch && (!deliveryAddress || intent === 'address_provided')) {
      deliveryAddress = addrLabelMatch[1].trim();
    }
    if (!deliveryAddress) {
      const addrKeywords = /\b(dha|clifton|gulshan|phase|block|street|road|avenue|lane|sector|town|garden|colony|defence|bahria|nazimabad|korangi|malir|johar|askari|highway|rd\b)/i;
      const addrMatch = combinedForAddr.match(new RegExp(`[\\w\\s,\\.\\-\\/]{0,30}${addrKeywords.source}[\\w\\s,\\.\\-\\/]{0,40}`, 'i'));
      if (addrMatch) deliveryAddress = addrMatch[0].trim();
    }

    let paymentMethod = recordData.payment_method || null;
    if (!paymentMethod) {
      const combined = msgLower + ' ' + aiReply.toLowerCase();
      if (/\bcod\b|cash\s+on\s+delivery/.test(combined)) paymentMethod = 'COD';
      else if (/easypaisa/.test(combined)) paymentMethod = 'Easypaisa';
      else if (/jazzcash/.test(combined)) paymentMethod = 'JazzCash';
      else if (/bank\s*transfer/.test(combined)) paymentMethod = 'Bank Transfer';
    }

    const calculatedTotal = orderTotal > 0 ? orderTotal : currentItems.reduce((s, i) => s + ((i.price || 0) * (i.qty || 1)), 0);

    const aiConfirmed = /confirm ho gaya|order confirm|order placed|confirmed your order|order ki tayari|order accept/i.test(aiReply);
    let newStatus;
    if (intent === 'order_confirmed' || aiConfirmed) {
      newStatus = 'confirmed';
    } else if (deliveryAddress && paymentMethod) {
      newStatus = 'pending';
    } else if (deliveryAddress || intent === 'address_provided') {
      newStatus = 'pending';
    } else {
      newStatus = ['confirmed', 'pending', 'processing'].includes(recordData.status) ? recordData.status : 'pending_address';
    }

    recordData = {
      ...recordData,
      tenant_id: ctx.tenant_id,
      conversation_id: ctx.conversation_id,
      customer_phone: ctx.customer_phone,
      customer_name: ctx.customer_name,
      niche: niche,
      items: currentItems.length > 0 ? currentItems : [{ name: 'Item from chat', qty: 1, price: 0 }],
      order_amount: calculatedTotal,
      payment_method: paymentMethod,
      delivery_address: deliveryAddress,
      source: ctx.platform || 'whatsapp',
      handled_by: 'bot',
      status: newStatus,
    };

    if (intent === 'order_confirmed' || aiConfirmed) {
      recordData.confirmed_at = new Date().toISOString();
    }
  }
}

// ═══════════════════════════════════════════════════════════════
// DENTAL / SALON / CLINIC
// ═══════════════════════════════════════════════════════════════
if (['dental', 'salon', 'clinic'].includes(niche)) {
  if (['booking_intent', 'appointment_confirmed'].includes(intent)) {
    createRecord = true;
    recordType = 'appointment';

    const timeMatch = (msg + ' ' + aiReply).match(/(\d{1,2})(:\d{2})?\s*(am|pm|AM|PM)/);
    const dayMatch = (msg + ' ' + aiReply).match(/(monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow|kal|parso)/i);

    let apptDate = recordData.appointment_date || null;
    let apptTime = recordData.appointment_time || null;

    if (dayMatch && !apptDate) {
      const dayMap = { tomorrow:1,kal:1,parso:2,monday:0,tuesday:1,wednesday:2,thursday:3,friday:4,saturday:5,sunday:6 };
      const day = dayMatch[1].toLowerCase();
      const d2 = new Date();
      if (['tomorrow','kal','parso'].includes(day)) {
        d2.setDate(d2.getDate() + (dayMap[day] || 1));
      } else {
        const target = dayMap[day];
        const today = d2.getDay();
        const diff = (target - today + 7) % 7 || 7;
        d2.setDate(d2.getDate() + diff);
      }
      apptDate = d2.toISOString().split('T')[0];
    }

    if (timeMatch && !apptTime) {
      const hour = parseInt(timeMatch[1]);
      const isPM = timeMatch[3].toLowerCase() === 'pm';
      const hour24 = isPM && hour !== 12 ? hour + 12 : (!isPM && hour === 12 ? 0 : hour);
      apptTime = `${String(hour24).padStart(2,'0')}:00:00`;
    }

    recordData = {
      ...recordData,
      tenant_id: ctx.tenant_id,
      conversation_id: ctx.conversation_id,
      patient_name: ctx.customer_name,
      patient_phone: ctx.customer_phone,
      niche: niche,
      service_type: recordData.service_type || 'Consultation',
      appointment_date: apptDate,
      appointment_time: apptTime,
      status: intent === 'appointment_confirmed' ? 'confirmed' : 'pending',
      is_new_patient: ctx.is_new_conversation,
    };
  }
}

// ═══════════════════════════════════════════════════════════════
// REAL ESTATE
// ═══════════════════════════════════════════════════════════════
if (niche === 'realestate') {
  if (['property_inquiry','requirement_provided','visit_request'].includes(intent)) {
    createRecord = true;
    recordType = 'lead';

    const budgetMatch = msg.match(/(\d+\.?\d*)\s*(crore|lakh|cr|lac)/i);
    let budgetMax = recordData.budget_max || null;
    if (budgetMatch && !budgetMax) {
      const num = parseFloat(budgetMatch[1]);
      const unit = budgetMatch[2].toLowerCase();
      budgetMax = ['crore','cr'].includes(unit) ? num * 10000000 : num * 100000;
    }

    const bedMatch = msg.match(/(\d+)\s*(bed|bedroom|br)/i);
    let bedrooms = recordData.bedrooms || null;
    if (bedMatch && !bedrooms) bedrooms = parseInt(bedMatch[1]);

    recordData = {
      ...recordData,
      tenant_id: ctx.tenant_id,
      conversation_id: ctx.conversation_id,
      customer_name: ctx.customer_name,
      customer_phone: ctx.customer_phone,
      intent: recordData.intent || (msgLower.includes('rent') ? 'rent' : msgLower.includes('sell') ? 'sell' : 'buy'),
      bedrooms,
      budget_max: budgetMax,
      stage: intent === 'visit_request' ? 'visit_scheduled' :
             intent === 'requirement_provided' ? 'qualified' : (recordData.stage || 'new_inquiry'),
      temperature: 'warm',
      last_activity_at: new Date().toISOString(),
    };
  }
}

const needs_human_handoff = /human|agent|representative|insaan|baat|connect|transfer/i.test(msgLower);

return [{
  json: {
    ...ctx,
    detected_intent: intent,
    create_record: createRecord,
    record_type: recordType,
    record_data: recordData,
    needs_human_handoff: needs_human_handoff
  }
}];

